<template>
  <AppLoader v-if="isLoading" subject="invitation" />
  <AppError v-else-if="error && error.statusCode !== 404" :error="error" variant="page" />
  <AppEmpty v-else-if="!companyInfo" subject="invitation" />
  <section v-else class="flex flex-col gap-10 max-w-2xl mx-auto">
    <div class="flex flex-col items-center text-center gap-6 pt-4 sm:pt-8">
      <div class="flex items-center gap-4 sm:gap-6">
        <div
          class="flex items-center justify-center h-24 w-24 rounded-2xl bg-background ring-1 ring-border shadow-sm p-3"
        >
          <Logo2 class="h-full w-auto text-foreground" />
        </div>
        <span class="text-4xl font-light text-muted-foreground select-none" aria-hidden="true">&times;</span>
        <div class="relative h-24 w-24">
          <div
            v-show="!logoLoaded || logoFailed"
            class="absolute inset-0 flex items-center justify-center rounded-2xl bg-background ring-1 ring-border shadow-sm p-3"
          >
            <Building2 class="h-2/3 w-auto text-muted-foreground" />
          </div>
          <img
            v-if="!logoFailed && companyInfo.logo_url"
            :src="companyInfo.logo_url"
            :alt="companyInfo.name"
            class="absolute inset-0 h-24 w-24 rounded-2xl object-cover ring-1 ring-border shadow-sm transition-opacity duration-200"
            :class="logoLoaded ? 'opacity-100' : 'opacity-0'"
            @load="logoLoaded = true"
            @error="logoFailed = true"
          />
        </div>
      </div>
      <div class="flex flex-col gap-3">
        <span class="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
          You've been invited by
        </span>
        <h1 class="text-3xl sm:text-4xl font-bold tracking-tight">{{ companyInfo.name }}</h1>
        <p class="text-base text-muted-foreground max-w-xl">
          Join Patriot Grassroots as a subcontractor canvasser and start working on real campaigns with this team.
        </p>
      </div>
    </div>

    <Card>
      <CardHeader>
        <CardTitle>Create your account</CardTitle>
        <CardDescription>Fill in your details below to get started.</CardDescription>
      </CardHeader>
      <CardContent>
        <form class="grid grid-cols-2 gap-4" @submit="onSubmit">
          <FormItemWrapper name="first_name" label="First Name" item-class="col-span-2 sm:col-span-1">
            <template #default="{ slots }">
              <Input
                id="first_name"
                type="text"
                placeholder="John"
                v-bind="slots.componentField"
                :disabled="isSigningUp"
                autocomplete="given-name"
              />
            </template>
          </FormItemWrapper>
          <FormItemWrapper name="last_name" label="Last Name" item-class="col-span-2 sm:col-span-1">
            <template #default="{ slots }">
              <Input
                id="last_name"
                type="text"
                placeholder="Doe"
                v-bind="slots.componentField"
                :disabled="isSigningUp"
                autocomplete="family-name"
              />
            </template>
          </FormItemWrapper>
          <FormItemWrapper name="email" label="Email" item-class="col-span-2 sm:col-span-1">
            <template #default="{ slots }">
              <Input
                id="email"
                type="text"
                placeholder="name@example.com"
                v-bind="slots.componentField"
                :disabled="isSigningUp"
                autocomplete="username"
              />
            </template>
          </FormItemWrapper>
          <FormItemWrapper name="phone" label="Phone Number" item-class="col-span-2 sm:col-span-1">
            <template #default="{ slots }">
              <Input
                id="phone"
                v-maska
                type="text"
                placeholder="+1 555-555-5555"
                data-maska="+# ###-###-####"
                v-bind="slots.componentField"
                :disabled="isSigningUp"
                autocomplete="tel"
              />
            </template>
          </FormItemWrapper>
          <FormItemWrapper name="password" label="Password" item-class="col-span-2">
            <template #default="{ slots }">
              <KitFormPasswordInput
                id="password"
                placeholder="Enter your password"
                :component-field="slots.componentField"
                :disabled="isSigningUp"
                autocomplete="new-password"
              />
            </template>
          </FormItemWrapper>
          <FormItemWrapper name="confirm_password" label="Confirm Password" item-class="col-span-2">
            <template #default="{ slots }">
              <KitFormPasswordInput
                id="confirm_password"
                placeholder="Confirm your password"
                :component-field="slots.componentField"
                :disabled="isSigningUp"
                autocomplete="new-password"
              />
            </template>
          </FormItemWrapper>
          <FormItemWrapper
            name="sms_consent"
            type="checkbox"
            :unchecked-value="false"
            :checked-value="true"
            item-class="col-span-2"
          >
            <template #default="{ slots }">
              <div class="flex flex-row items-start gap-2">
                <Checkbox
                  id="sms_consent"
                  data-testid="signup-sms-consent"
                  :model-value="slots.value"
                  v-bind="slots.componentField"
                  :disabled="isSigningUp"
                  class="mt-0.5"
                />
                <div class="flex flex-col gap-0.5">
                  <Label for="sms_consent" class="text-sm font-normal">
                    Text me about work opportunities from Patriot Grassroots
                  </Label>
                  <p class="text-xs text-description">
                    Automated texts; consent is not a condition of registration. Message frequency varies, message &amp;
                    data rates may apply. Reply STOP to opt out or HELP for help.
                  </p>
                </div>
              </div>
            </template>
          </FormItemWrapper>
          <FormItemWrapper
            name="agreed_to_terms"
            type="checkbox"
            :unchecked-value="false"
            :checked-value="true"
            item-class="col-span-2"
          >
            <template #default="{ slots }">
              <div class="flex flex-row items-center gap-2">
                <Checkbox
                  id="agreed_to_terms"
                  :model-value="slots.value"
                  v-bind="slots.componentField"
                  :disabled="isSigningUp"
                />
                <Label for="agreed_to_terms" class="text-sm font-normal">
                  I agree to the
                  <NuxtLink :to="{ name: 'privacy' }" target="_blank" class="underline"
                    >Terms &amp; Conditions</NuxtLink
                  >
                </Label>
              </div>
            </template>
          </FormItemWrapper>
          <Button
            variant="default"
            class="w-full h-10 col-span-2"
            :loading="isSigningUp"
            :disabled="isSigningUp"
            type="submit"
          >
            Sign Up
          </Button>
        </form>
      </CardContent>
    </Card>
  </section>
</template>

<script setup lang="ts">
import { useForm } from 'vee-validate';
import { toTypedSchema } from '@vee-validate/zod';
import { useSignUp } from '~/mutations/signUp';
import { signUpFormSchema } from '~/constants/validationSchemas/signUp';
import { getSubcontractorCompanyPublicInfoBySignUpCode } from '~/client';
import { Building2 } from 'lucide-vue-next';
import Logo2 from '~/assets/icons/logo2.svg';

definePageMeta({
  layout: 'share',
  auth: {
    unauthenticatedOnly: true,
    navigateAuthenticatedTo: '/projects',
  },
  subcontractorPublic: true,
});

useSeoMeta({
  title: 'Subcontractor Canvasser Sign Up',
  description: 'Sign up as a subcontractor canvasser invited by a subcontractor company.',
});

const route = useRoute('sign-up-company-code');
const code = computed(() => route.params.code);

const {
  data: companyInfo,
  error,
  isLoading,
} = useQuery({
  key: () => ['subcontractor-company.public-info', code.value],
  query: () =>
    getSubcontractorCompanyPublicInfoBySignUpCode({
      composable: '$fetch',
      path: { sign_up_code: code.value },
    }),
});

// NOTE: @pinia/colada's useQuery does not expose a per-query onError hook,
// so we watch the error ref and inspect FetchError.statusCode here.
watch(
  () => error.value,
  (newError) => {
    if (!newError) return;
    if (newError.statusCode === 404) {
      throw createError({
        statusCode: 404,
        statusMessage: `Page not found: ${route.path}`,
        fatal: true,
      });
    }
  }
);

const logoFailed = ref(false);
const logoLoaded = ref(false);

watch(
  () => companyInfo.value?.logo_url,
  () => {
    logoFailed.value = false;
    logoLoaded.value = false;
  }
);

const { signUp, isSigningUp } = useSignUp();

const { handleSubmit } = useForm({
  validationSchema: toTypedSchema(signUpFormSchema),
});

const onSubmit = handleSubmit(({ confirm_password: _ignore, ...form }) => {
  signUp({
    ...form,
    // handleSubmit only fires once the schema validated agreed_to_terms === true.
    agreed_to_terms: true,
    subcontractor_company_code: code.value,
    time_zone: Intl.DateTimeFormat().resolvedOptions().timeZone,
  });
});
</script>
